import { DeskRouteAPI, VERSION } from './api.js';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty = v => String(v || '').replaceAll('_',' ').replace(/\b\w/g, c => c.toUpperCase());
const date = v => v ? new Date(v).toLocaleString('en-GB', {day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}) : '—';
const relative = v => { const m = Math.max(0, Math.floor((Date.now()-new Date(v))/60000)); return m < 1 ? 'now' : m < 60 ? `${m} min` : m < 1440 ? `${Math.floor(m/60)} hr` : `${Math.floor(m/1440)} days`; };
const uuid = v => /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(v || '');
const badge = (v, tone='') => `<span class="badge ${tone}">${esc(v)}</span>`;
const button = (text, action, extra='', tone='') => `<button type="button" class="button ${tone}" data-action="${action}" ${extra}>${esc(text)}</button>`;
const empty = (title, text='') => `<div class="empty"><h2>${esc(title)}</h2><p>${esc(text)}</p></div>`;
const metric = (label, value, hint='') => `<div class="card metric"><span class="metric-label">${esc(label)}</span><strong>${esc(value ?? '—')}</strong><p>${esc(hint)}</p></div>`;
const kv = obj => `<dl class="key-values">${Object.entries(obj).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v ?? '—')}</dd>`).join('')}</dl>`;
const field = (id, label, value='', type='text', extra='') => `<div class="field"><label for="${id}">${esc(label)}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const options = (items, selected) => items.map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`).join('');
const pages = {
 inbox:['Inbox','Every customer conversation, in one place'],human:['Human Queue','AI only sends work it cannot answer safely'],brain:['Business Brain','Approved knowledge, learning and gaps'],automations:['Automations','Routing, timing and escalation rules'],analytics:['Analytics','Support performance and knowledge coverage'],channels:['Channels','Website chat, email and messaging connections'],help:['Help Centre','Publish clear answers for your customers'],team:['Team','Roles and human workload'],settings:['Settings','Workspace, AI controls and notifications'],alerts:['Notifications','Assignments, mentions and SLA alerts'],review:['Review Queue','AI drafts waiting for a human decision'],autosetup:['AutoSetup','Learn from your authorised website'],brands:['Brands','Business identities and knowledge boundaries'],billing:['Billing','Plan and usage'],audit:['Audit','Traceable workspace actions']
};
const state = {workspaces:[],workspace:null,brands:[],brand:null,permissions:{},page:'inbox',routeId:0,threadId:0,selected:null,conversations:[],contacts:{},members:[],filter:'all',search:'',mode:'reply',drafts:new Map(),notifications:[],device:null,timer:null,installPrompt:null};
const api = new DeskRouteAPI({onExpired:()=>showLogin('Your session ended. Please sign in again.')});
const org = () => state.workspace?.id;
const user = () => api.session?.user?.id;
const allowed = p => state.permissions[p] === true;
const scope = (extra={}, brand=false) => ({organisation_id:`eq.${org()}`,...(brand&&state.brand?{brand_id:`eq.${state.brand}`} : {}),...extra});
const rows = (table, extra={}, brand=false) => api.table('cxroute_'+table, scope(extra,brand));
let toastTimer;
function toast(message, error=false) { clearTimeout(toastTimer); $('#toast').textContent=message; $('#toast').className='toast'+(error?' error':''); toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),6000); }
function showLogin(message='') { clearInterval(state.timer); state.routeId++; state.threadId++; state.drafts.clear(); state.workspace=null; state.notifications=[]; $('#appView').classList.add('hidden'); $('#loginView').classList.remove('hidden'); $('#content').replaceChildren(); $('#password').value=''; if(message){$('#loginError').textContent=message;$('#loginError').classList.remove('hidden');} }
function menu(open) { $('#sidebar').classList.toggle('open',open); $('#menuShade').classList.toggle('hidden',!open); $('#menuButton').setAttribute('aria-expanded',String(open)); if(open)$('#closeMenu').focus(); }
function modal(title,html) { $('#modalContent').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${button('Close','close-modal')}</div>${html}`; $('#modal').showModal(); }
function renderNav() {
 const main=['inbox','human','brain','automations','analytics','channels','help','team','settings'];
 $('#nav').innerHTML=main.map(p=>`<button class="nav-item ${state.page===p?'active':''}" data-page="${p}" ${state.page===p?'aria-current="page"':''}><img src="./assets/nav-${state.page===p?'active':'dot'}.svg" alt=""><span>${pages[p][0]}</span><span id="count-${p}" class="nav-count hidden"></span></button>`).join('');
 $('#bottomNav').innerHTML=[['inbox','Inbox'],['human','Human'],['alerts','Alerts'],['brain','Brain'],['more','More']].map(([p,label])=>`<button class="bottom-item ${state.page===p?'active':''}" ${p==='more'?'data-action="open-menu"':`data-page="${p}"`}><img src="./assets/nav-${state.page===p?'active':'dot'}.svg" alt="">${label}</button>`).join('');
 const settings=state.workspace?.settings||{};
 $('#aiMode').textContent=`${pretty(settings.ai_mode||'approve')} · ${Math.round((settings.auto_answer_min_confidence??0.9)*100)}%`;
 $('#accountButton').textContent=`${state.workspace?.display_name||'My account'} · ${pretty(state.workspace?.role||'member')}`;
}
async function loadWorkspace() {
 const result=await api.onboard('me'); state.workspaces=result.workspaces||[];
 if(!state.workspaces.length)throw new Error('No workspace is linked to this account. Ask your workspace owner for access.');
 const saved=localStorage.getItem('drw'); state.workspace=state.workspaces.find(w=>w.id===saved)||state.workspaces[0];
 $('#workspace').innerHTML=options(state.workspaces.map(w=>[w.id,w.profile?.display_name||w.name]),org());
 await loadWorkspaceData();
}
async function loadWorkspaceData() {
 localStorage.setItem('drw',org()); state.selected=null; state.drafts.clear(); state.device=null; state.notifications=[]; state.permissions={}; state.members=[];
 const permissionNames=['inbox.read','inbox.reply','inbox.manage','knowledge.manage','automation.manage','channels.manage'];
 const results=await Promise.allSettled([rows('brands',{select:'id,name,enabled,is_default,website_url,support_email',enabled:'eq.true',order:'is_default.desc,name.asc'}),...permissionNames.map(p=>api.rpc('cxroute_has_permission',{p_organisation_id:org(),p_permission:p}))]);
 if(results[0].status!=='fulfilled')throw results[0].reason;
 state.brands=results[0].value;state.brand=state.brands[0]?.id||null;
 permissionNames.forEach((p,i)=>{state.permissions[p]=results[i+1].status==='fulfilled'&&results[i+1].value===true;});
 // Standard roles remain readable if a custom permission is not defined in an older workspace.
 if(['owner','admin','agent'].includes(state.workspace.role)){state.permissions['inbox.reply']=true;state.permissions['inbox.manage']=true;}
 if(['owner','admin'].includes(state.workspace.role))for(const p of permissionNames)state.permissions[p]=true;
 renderNav();
}
function route(page,id=null) { if(!pages[page])page='inbox'; const hash=page+(uuid(id)?'/'+id:''); if(location.hash.slice(1)!==hash)location.hash=hash;else renderRoute(); }
async function renderRoute() {
 if(!state.workspace)return;
 const [raw,id]=location.hash.slice(1).split('/'); const page=pages[raw]?raw:'inbox'; const seq=++state.routeId;state.threadId++;
 state.page=page;state.selected=page==='inbox'&&uuid(id)?id:null; menu(false);renderNav();
 $('#pageTitle').textContent=pages[page][0]; $('#pageSubtitle').textContent=pages[page][1]; document.title=`${pages[page][0]} · DeskRoute`;
 $('#content').className=page==='inbox'?'inbox-page':'';$('#content').innerHTML=empty('Loading…');
 try{const result=await renderers[page]();if(seq!==state.routeId)return;$('#content').innerHTML=result;bindPage();if(page==='inbox'&&state.selected)await openThread(state.selected);}
 catch(error){if(seq!==state.routeId)return;$('#content').innerHTML=`<div class="card">${empty('This page could not load',error.message)}${button('Try again','retry')}</div>`;}
}
function brandSelect(){return state.brands.length>1?`<label class="sr-only" for="brandSelect">Brand</label><select id="brandSelect">${options(state.brands.map(b=>[b.id,b.name]),state.brand)}</select>`:'';}
async function fetchInbox() {
 const [cv,ct]=await Promise.all([rows('conversations',{select:'id,contact_id,channel,subject,status,priority,unread_count,assigned_user_id,created_at,updated_at,tags,brand_id,first_response_due_at,resolution_due_at',order:'updated_at.desc',limit:'200'}),rows('contacts',{select:'id,name,email,phone',limit:'1000'})]);
 state.conversations=cv;state.contacts=Object.fromEntries(ct.map(c=>[c.id,c]));
}
const contact = c => state.contacts[c.contact_id]||{};
const name = c => contact(c).name||contact(c).email||'Customer';
const needsHuman = c => ['open','pending'].includes(c.status)&&(c.tags||[]).includes('ai-needs-human');
function visibleConversations(){return state.conversations.filter(c=>{const q=state.search.toLowerCase();const search=!q||[c.subject,name(c),contact(c).email,c.channel].some(v=>String(v||'').toLowerCase().includes(q));return search&&(state.filter==='all'||state.filter==='mine'&&c.assigned_user_id===user()||state.filter==='unassigned'&&!c.assigned_user_id||state.filter==='open'&&['open','pending'].includes(c.status));});}
function ticketRows(){const cv=visibleConversations();return cv.map(c=>`<button class="ticket-row ${state.selected===c.id?'active':''}" data-conversation="${c.id}" aria-label="Open conversation with ${esc(name(c))}"><div class="row"><span class="avatar">${esc(name(c).slice(0,1).toUpperCase())}</span><div class="ticket-person"><div class="ticket-name">${esc(name(c))}</div><div class="ticket-meta">${esc(pretty(c.channel))} · ${relative(c.updated_at)}</div></div>${needsHuman(c)?badge('Needs you','warning'):c.status==='resolved'?badge('Resolved','good'):''}</div><p class="subject">${esc(c.subject||'New conversation')}</p></button>`).join('')||empty('No conversations here','Try another filter or search.');}
async function inbox(){await fetchInbox();return `<div class="inbox ${state.selected?'has-selection':''}"><aside class="ticket-list" aria-label="Conversations"><div class="filters">${[['all','All'],['mine','Mine'],['unassigned','Unassigned'],['open','Open']].map(([v,t])=>`<button class="badge filter ${state.filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><input type="search" id="inboxSearch" placeholder="Search conversations…" aria-label="Search inbox" value="${esc(state.search)}"><div class="list-label">Conversations · ${state.conversations.length}${state.conversations.length===200?' most recent':''}</div><div id="ticketRows">${ticketRows()}</div></aside><section id="thread" class="thread" aria-label="Selected conversation">${empty('Select a conversation','Your customer messages and reply tools will appear here.')}</section><aside id="contextPanel" class="context-panel"><h3>Customer & AI context</h3><p class="muted">Open a conversation to see the details.</p></aside></div>`;}
async function loadMembers(){try{const d=await api.rpc('cxroute_team_directory',{p_organisation_id:org()});state.members=d.members||[];return state.members;}catch{return state.members.length?state.members:[{user_id:user(),display_name:state.workspace.display_name||'You',role:state.workspace.role}];}}
async function openThread(id){
 const seq=++state.threadId,workspace=org();state.selected=id;
 const c=state.conversations.find(c=>c.id===id);if(!c){$('#thread').innerHTML=empty('Conversation unavailable','It may have moved or you may not have access.');return;}
 const [ms,members]=await Promise.all([rows('messages',{conversation_id:`eq.${id}`,select:'id,direction,body,author_type,created_at,safe_metadata',order:'created_at.desc',limit:'200'}),loadMembers()]);
 if(seq!==state.threadId||workspace!==org()||state.page!=='inbox')return;
 ms.reverse();$('.inbox').classList.add('has-selection');$('#ticketRows').innerHTML=ticketRows();
 const active=state.drafts.get(id)||{reply:'',note:''};const can=allowed('inbox.reply');
 $('#thread').innerHTML=`<div class="thread-header"><button class="button subtle mobile-only thread-back" data-action="back-inbox">← Inbox</button><h2>${esc(name(c))}</h2><p>${esc(pretty(c.channel))} · ${esc(contact(c).email||'No email supplied')} · ${ms.length}${ms.length===200?' latest':''} messages</p><div class="ticket-controls"><label class="sr-only" for="ticketStatus">Status</label><select id="ticketStatus" ${!allowed('inbox.manage')?'disabled':''}>${options(['open','pending','resolved'].map(s=>[s,pretty(s)]),c.status)}</select><label class="sr-only" for="ticketPriority">Priority</label><select id="ticketPriority" ${!allowed('inbox.manage')?'disabled':''}>${options(['low','normal','high','urgent'].map(s=>[s,'Priority: '+pretty(s)]),c.priority)}</select><label class="sr-only" for="ticketAssignee">Assignee</label><select id="ticketAssignee" ${!allowed('inbox.manage')?'disabled':''}>${options([['','Unassigned'],...members.map(m=>[m.user_id,m.display_name||m.member_email||'Team member'])],c.assigned_user_id||'')}</select></div></div><div class="thread-body">${needsHuman(c)?`<div class="notice danger"><strong>AI needs a human</strong><p>DeskRoute could not safely answer from approved business knowledge. Review the question and help the customer.</p></div>`:''}<div class="messages">${ms.map(m=>`<div class="message ${m.direction==='inbound'?'inbound':m.direction==='internal'?'internal':'outbound'}"><div class="bubble">${esc(m.body)}</div><small>${m.direction==='internal'?'Internal note · only your team':m.author_type==='customer'?esc(name(c)):m.author_type==='ai'?'DeskRoute AI':'Team reply'} · ${date(m.created_at)}</small></div>`).join('')||empty('No messages yet')}</div></div><form id="replyForm" class="composer ${state.mode==='note'?'note-mode':''}"><div class="composer-tabs" role="tablist" aria-label="Message type"><button type="button" class="badge ${state.mode==='reply'?'active':''}" role="tab" aria-selected="${state.mode==='reply'}" data-compose="reply">Public Reply</button><button type="button" class="badge ${state.mode==='note'?'active':''}" role="tab" aria-selected="${state.mode==='note'}" data-compose="note">Internal Note</button></div><label class="sr-only" for="replyText">${state.mode==='note'?'Internal note':'Reply to customer'}</label><textarea id="replyText" maxlength="4000" placeholder="${state.mode==='note'?'Add a note for your team…':`Reply to ${esc(name(c))}…`}" ${can?'':'disabled'}>${esc(active[state.mode]||'')}</textarea><div id="mentionWrap" class="mention-field ${state.mode==='note'?'':'hidden'}"><label for="mentionUser">Mention a teammate</label><select id="mentionUser">${options([['','No mention'],...members.filter(m=>m.user_id!==user()).map(m=>[m.user_id,m.display_name||m.member_email||'Team member'])],'')}</select></div><p class="composer-hint" id="composeHint">${state.mode==='note'?'Private to your team. Never shown in the customer widget.':c.channel==='website_chat'?'Replies appear in the customer’s website chat when it reconnects.':'Sending on this channel is not enabled in this release. You can add an internal note.'}</p><div class="composer-footer"><button class="button primary" type="submit" id="sendReply" ${!can||state.mode==='reply'&&c.channel!=='website_chat'?'disabled':''}>${state.mode==='note'?'Add note':'Send reply'}</button>${button('Mark pending','ticket-status','data-status="pending"'+(!allowed('inbox.manage')?' disabled':''))}${button(c.status==='resolved'?'Reopen':'Resolve','ticket-status',`data-status="${c.status==='resolved'?'open':'resolved'}"`+(!allowed('inbox.manage')?' disabled':''),'success')}</div><p id="replyError" class="notice danger hidden" role="alert"></p></form>`;
 $('#contextPanel').innerHTML=`<h3>Customer & AI context</h3><div class="card"><strong>${esc(name(c))}</strong><p class="muted">${esc(contact(c).email||'No email supplied')}</p><p>${esc(pretty(c.channel))} · ${relative(c.updated_at)}</p></div><h3>Business Brain</h3><div class="card"><p>${needsHuman(c)?'This conversation needs a verified human answer.':'Answers use your workspace’s approved knowledge policy.'}</p>${button('Open Business Brain','go-brain')}</div><h3>Ticket details</h3><div class="card">${kv({Status:pretty(c.status),Priority:pretty(c.priority),Assignee:members.find(m=>m.user_id===c.assigned_user_id)?.display_name||'Unassigned',Channel:pretty(c.channel),'Response due':date(c.first_response_due_at),Tags:(c.tags||[]).join(', ')||'—'})}</div>`;
 const body=$('.thread-body');body.scrollTop=body.scrollHeight;
 $('#replyText').addEventListener('input',()=>{const drafts=state.drafts.get(id)||{reply:'',note:''};drafts[state.mode]=$('#replyText').value;state.drafts.set(id,drafts);});
 $('#replyForm').onsubmit=async event=>{event.preventDefault();if(event.currentTarget.dataset.submitting)return;const text=$('#replyText').value.trim();if(!text)return;const form=event.currentTarget;form.dataset.submitting='true';const mode=state.mode,mention=$('#mentionUser').value;const send=$('#sendReply');send.disabled=true;$('#replyError').classList.add('hidden');
   try{if(mode==='note')await api.rpc('cxroute_add_internal_note',{p_conversation_id:id,p_body:text,p_mention_user_ids:mention?[mention]:[]});else { const pending=state.drafts.get(id)||{reply:text,note:''}; if(!pending.clientId||pending.lastAttemptBody!==text){pending.clientId=crypto.randomUUID();pending.lastAttemptBody=text;} state.drafts.set(id,pending); await api.rpc('cxroute_send_website_reply',{p_conversation_id:id,p_body:text,p_client_id:pending.clientId,p_draft_id:pending.aiDraftId||null}); }
   const draft=state.drafts.get(id)||{reply:'',note:''};draft[mode]='';if(mode==='reply'){delete draft.clientId;delete draft.lastAttemptBody;delete draft.aiDraftId;}state.drafts.set(id,draft);
   if(state.selected===id&&workspace===org()){await openThread(id);toast(mode==='note'?'Internal note added.':'Reply saved to the customer chat.');}}
   catch(error){if(state.selected===id){$('#replyError').textContent=error.message;$('#replyError').classList.remove('hidden');}}finally{delete form.dataset.submitting;if(send.isConnected)send.disabled=false;}};
 $('#ticketStatus').onchange=e=>ticketUpdate({status:e.target.value});$('#ticketPriority').onchange=e=>ticketUpdate({priority:e.target.value});$('#ticketAssignee').onchange=e=>ticketUpdate({assigned_user_id:e.target.value||null});
}
async function ticketUpdate(patch){const id=state.selected;if(!id||!allowed('inbox.manage'))return;const c=state.conversations.find(c=>c.id===id);if(patch.status)patch.resolved_at=patch.status==='resolved'?new Date().toISOString():null;try{const changed=await api.patch('cxroute_conversations',org(),id,{...patch,updated_at:new Date().toISOString()});Object.assign(c,changed[0]);if(state.selected===id)await openThread(id);toast('Conversation updated.');}catch(error){toast(error.message,true);if(state.selected===id)await openThread(id);}}
async function human(){await fetchInbox();const queue=state.conversations.filter(needsHuman);return `<div class="section-head row between"><div><h2 class="page-heading">Needs you</h2><p>AI only sends work it cannot answer safely.</p></div>${badge(queue.length+' need you',queue.length?'danger':'good')}</div><div class="human-grid">${queue.map(c=>`<button class="card human-card" data-conversation="${c.id}"><h3>${esc(name(c))}</h3><p class="subject">${esc(c.subject||'A customer needs your help')}</p><div class="tiny muted">${esc(pretty(c.channel))} · ${relative(c.updated_at)}</div>${badge(c.assigned_user_id===user()?'Assigned to you':'Needs a human','warning')}</button>`).join('')}</div>${!queue.length?`<div class="card">${empty('You’re all caught up','No conversations need a human right now.')}</div>`:''}<p class="small muted" style="margin-top:16px">Showing the latest ${state.conversations.length} conversations. ${button('Review AI drafts','go-review')}</p>`;}
async function brain(){const [facts,gaps,suggestions]=await Promise.all([rows('knowledge_facts',{select:'id,fact_key,fact_value,confidence,review_status,category,source_label,valid_until,updated_at',order:'updated_at.desc',limit:'200'},true),rows('knowledge_gaps',{select:'id,example_question,reason,status,occurrences',status:'eq.open',order:'last_seen_at.desc',limit:'50'},true),rows('learning_suggestions',{select:'id,question,proposed_answer,status',status:'eq.pending',limit:'50'},true)]);state.facts=facts;state.suggestions=suggestions;return `<div class="stack"><div class="notice row between wrap"><div><strong>Knowledge boundary</strong><p class="small muted">AI answers from approved facts. Website scans and learned replies stay pending until reviewed.</p></div><div class="row">${brandSelect()}${allowed('knowledge.manage')?button('Add fact','add-fact','','primary'):''}${button('Scan website','go-autosetup')}</div></div><div class="grid wide-narrow"><div class="card"><div class="section-head"><h3>Knowledge facts</h3><p>${facts.filter(f=>f.review_status==='approved').length} approved · ${facts.filter(f=>f.review_status==='pending').length} pending · ${facts.length} shown</p></div>${facts.map(f=>`<details class="fact-item"><summary><strong>${esc(f.fact_key)}</strong><span class="muted">${esc(pretty(f.category))}</span>${badge(pretty(f.review_status),f.review_status==='approved'?'good':'warning')}</summary><div class="fact-detail"><p class="fact-value">${esc(f.fact_value)}</p><p class="tiny muted">${Math.round(f.confidence*100)}% confidence · ${esc(f.source_label||'Manual fact')}${f.valid_until?' · Expires '+date(f.valid_until):''}</p><div class="row">${allowed('knowledge.manage')?button('Edit','edit-fact',`data-id="${f.id}"`):''}${allowed('knowledge.manage')&&f.review_status==='pending'?button('Approve','approve-fact',`data-id="${f.id}"`,'primary')+button('Reject','reject-fact',`data-id="${f.id}"`):''}</div></div></details>`).join('')||empty('No facts yet','Add a fact or scan your business website.')}</div><div class="stack"><div class="card"><div class="section-head"><h3>Knowledge gaps</h3><p>Questions DeskRoute could not safely answer</p></div><div class="stack">${gaps.map(g=>`<div class="gap-card"><strong>${esc(g.example_question)}</strong><p>${esc(pretty(g.reason))} · ${g.occurrences} occurrence${g.occurrences===1?'':'s'}</p>${allowed('knowledge.manage')?button('Teach an answer','teach-gap',`data-question="${esc(g.example_question)}"`):''}</div>`).join('')||'<p class="small muted">No open knowledge gaps.</p>'}</div></div><div class="card"><div class="section-head"><h3>Learning queue</h3><p>Staff replies become pending FAQ candidates</p></div>${suggestions.map(s=>`<div class="fact-item"><strong>${esc(s.question)}</strong><p class="fact-value small">${esc(s.proposed_answer)}</p>${allowed('knowledge.manage')?button('Approve answer','approve-learning',`data-id="${s.id}"`,'primary'):badge('Awaiting manager review','warning')}</div>`).join('')||`${badge('0 pending suggestions','good')}<p class="small muted" style="margin-top:16px">When a human answers a customer, DeskRoute can propose that answer here for review.</p>`}</div></div></div></div>`;}
function factEditor(f={},question=''){modal(f.id?'Edit knowledge fact':'Add knowledge fact',`<form id="factForm" class="form">${field('factKey','Fact name',f.fact_key||'','text','required maxlength="160"') }<div class="field"><label for="factValue">Verified answer</label><textarea id="factValue" required maxlength="8000">${esc(f.fact_value||(question?`Question: ${question}\nAnswer: `:''))}</textarea></div>${field('factCategory','Category',f.category||'faq','text','required')}${field('factConfidence','Confidence (%)',Math.round((f.confidence??0.95)*100),'number','min="0" max="100" required')}<p class="small muted">Saving returns this fact to pending review. Approve it only after checking the answer.</p><div id="formError" class="notice danger hidden" role="alert"></div><div class="dialog-actions">${button('Cancel','close-modal')}<button class="button primary">Save for review</button></div></form>`);$('#factForm').onsubmit=e=>submitForm(e,async()=>{const body={fact_key:$('#factKey').value.trim(),fact_value:$('#factValue').value.trim(),category:$('#factCategory').value.trim(),confidence:Number($('#factConfidence').value)/100,review_status:'pending',approved_by:null,approved_at:null,updated_at:new Date().toISOString()};if(f.id)await api.patch('cxroute_knowledge_facts',org(),f.id,body);else await api.table('cxroute_knowledge_facts',{}, {method:'POST',body:{...body,organisation_id:org(),brand_id:state.brand,origin_type:'manual',source_label:'Workspace team',created_by:user()}});$('#modal').close();route('brain');toast('Fact saved for review.');});}
async function submitForm(event,work){event.preventDefault();const form=event.currentTarget;if(form.dataset.submitting)return;form.dataset.submitting='true';const submit=$('button[type=submit],button:not([type]):not([data-action])',form);if(submit)submit.disabled=true;try{await work();}catch(error){const el=$('#formError',form)||$('#formError');if(el){el.textContent=error.message;el.classList.remove('hidden');}else toast(error.message,true);}finally{delete form.dataset.submitting;if(submit?.isConnected)submit.disabled=false;}}
async function automations(){const rules=await rows('routing_rules',{select:'id,name,enabled,sort_order,conditions,actions,stop_processing,trigger_type,brand_id',order:'sort_order.asc,created_at.asc'});state.rules=rules;return `<div class="stack"><div class="card row between wrap"><div class="section-head"><h3>Automation builder</h3><p>Trigger → conditions → actions. Keep rules readable and auditable.</p></div>${allowed('automation.manage')?button('New automation','new-rule','','primary'):badge('Read only')}</div><div class="grid wide-narrow"><div class="card"><div class="section-head"><h3>Active automations</h3><p>Ordered rules run from top to bottom.</p></div><div class="stack">${rules.map(r=>`<div class="rule"><div class="row between"><h3>${esc(r.name)}</h3>${allowed('automation.manage')?button(r.enabled?'On':'Off','toggle-rule',`data-id="${r.id}"`,r.enabled?'success':''):badge(r.enabled?'On':'Off',r.enabled?'good':'')}</div><p class="muted">${esc(pretty(r.trigger_type))} · ${esc(Object.entries(r.conditions||{}).map(([k,v])=>pretty(k)+': '+v).join(' · ')||'Every inbound message')}</p><p>${esc(Object.entries(r.actions||{}).map(([k,v])=>pretty(k)+': '+(Array.isArray(v)?v.join(', '):v)).join(' · '))}</p>${allowed('automation.manage')?button('Edit','edit-rule',`data-id="${r.id}"`):''}</div>`).join('')||empty('No routing rules yet','Add a rule to route new website messages.')}</div></div><div class="card"><h3>Start with a clear rule</h3><p class="small muted">Choose an incoming channel or a word in the message, then set priority, assign a teammate or add a tag.</p><div class="stack">${badge('New customer message')}${badge('Urgent keyword')}${badge('Assign a teammate')}${badge('Add a routing tag')}</div><p class="small muted" style="margin-top:24px">New rules start disabled. Review the conditions before switching them on. Existing time-based rules are visible here; their scheduler needs a separate operational check.</p></div></div></div>`;}
async function ruleEditor(rule={}){const members=await loadMembers();if(rule.id&&rule.trigger_type!=='inbound_message'){toast('Time-based rules require an administrator to review the scheduler before editing.',true);return;}modal(rule.id?'Edit automation':'New automation',`<form id="ruleForm" class="form">${field('ruleName','Rule name',rule.name||'','text','required maxlength="120"')}<div class="field"><label for="ruleChannel">When a message arrives on</label><select id="ruleChannel">${options([['','Any channel'],['website_chat','Website chat'],['email','Email']],rule.conditions?.channel||'')}</select></div>${field('ruleContains','Message contains (optional)',rule.conditions?.body_contains||'') }<div class="field"><label for="rulePriority">Set priority</label><select id="rulePriority">${options([['','Leave unchanged'],...['low','normal','high','urgent'].map(x=>[x,pretty(x)])],rule.actions?.priority||'')}</select></div><div class="field"><label for="ruleAssignee">Assign to</label><select id="ruleAssignee">${options([['','Leave unchanged'],...members.map(m=>[m.user_id,m.display_name||m.member_email||'Team member'])],rule.actions?.assigned_user_id||'')}</select></div>${field('ruleTags','Add tags (comma separated)',(rule.actions?.add_tags||[]).join(', '))}${field('ruleOrder','Order',rule.sort_order??10,'number','min="0" max="10000" required')}<label class="row"><input id="ruleStop" type="checkbox" ${rule.stop_processing?'checked':''}> Stop after this rule matches</label><p class="small muted">Changes are saved with the rule disabled, ready for your review.</p><div id="formError" class="notice danger hidden" role="alert"></div><div class="dialog-actions">${button('Cancel','close-modal')}<button class="button primary">Save rule</button></div></form>`);$('#ruleForm').onsubmit=e=>submitForm(e,async()=>{const conditions={},actions={};if($('#ruleChannel').value)conditions.channel=$('#ruleChannel').value;if($('#ruleContains').value.trim())conditions.body_contains=$('#ruleContains').value.trim();if($('#rulePriority').value)actions.priority=$('#rulePriority').value;if($('#ruleAssignee').value)actions.assigned_user_id=$('#ruleAssignee').value;const tags=$('#ruleTags').value.split(',').map(x=>x.trim()).filter(Boolean);if(tags.length)actions.add_tags=tags;if(!Object.keys(actions).length)throw new Error('Choose at least one action.');const body={name:$('#ruleName').value.trim(),trigger_type:'inbound_message',conditions,actions,enabled:false,stop_processing:$('#ruleStop').checked,sort_order:Number($('#ruleOrder').value),updated_at:new Date().toISOString()};if(rule.id)await api.patch('cxroute_routing_rules',org(),rule.id,body);else await api.table('cxroute_routing_rules',{}, {method:'POST',body:{...body,organisation_id:org(),created_by:user(),brand_id:state.brand}});$('#modal').close();route('automations');toast('Rule saved, disabled for review.');});}
function readinessCard(r){if(!r)return `<div class="card"><h3>Business Brain readiness</h3><p class="muted">Choose a brand to see coverage.</p></div>`;return `<div class="card"><h3>Business Brain readiness</h3><div class="readiness">${Number(r.readiness_score||0)}%</div><p class="tiny muted">${Number(r.coverage_score||0)}% core coverage · ${Number(r.open_gaps||0)} open gap${r.open_gaps===1?'':'s'}</p><progress max="100" value="${Number(r.readiness_score||0)}" aria-label="Business Brain readiness"></progress><div class="topic-list">${(r.required_topics||[]).map(t=>badge(((r.present_topics||[]).includes(t)?'✓ ':'○ ')+pretty(t),(r.present_topics||[]).includes(t)?'good':'warning')).join('')}</div></div>`;}
async function analytics(){const [result,ready,cv]=await Promise.all([api.onboard('analytics',org(),{brandId:state.brand,days:30}),state.brand?api.rpc('cxroute_business_brain_readiness',{p_organisation_id:org(),p_brand_id:state.brand}):null,rows('conversations',{select:'id,created_at',created_at:'gte.'+new Date(Date.now()-7*86400000).toISOString(),order:'created_at.desc',limit:'1000'},true)]);const a=result.analytics||{};const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(6-i));const next=new Date(d);next.setDate(next.getDate()+1);return {label:d.toLocaleDateString('en-GB',{weekday:'short'}),value:cv.filter(c=>new Date(c.created_at)>=d&&new Date(c.created_at)<next).length};});const max=Math.max(1,...days.map(x=>x.value));return `<div class="stack"><div class="row between"><p class="muted small">Last 30 days · ${esc(state.brands.find(b=>b.id===state.brand)?.name||state.workspace.name)}</p>${brandSelect()}</div><div class="grid cols4 mobile-metrics">${metric('Conversations',a.conversations,'Across selected channels')}${metric('AI containment',`${a.ai_containment_rate??0}%`,'Automatic answers / AI decisions')}${metric('Human queue',a.human_queue,'Open and pending')}${metric('Open gaps',a.open_knowledge_gaps,'Needs teaching')}</div><div class="grid wide-narrow"><div class="card"><h3>Support volume</h3><p class="tiny muted">Customer conversations · last 7 days</p><div class="bar-chart" role="img" aria-label="${esc(days.map(d=>d.label+': '+d.value).join(', '))}">${days.map(d=>`<div class="bar-column"><span>${d.value}</span><div class="bar" style="height:${Math.max(2,d.value/max*170)}px"></div><span>${d.label}</span></div>`).join('')}</div><p class="bar-caption">${cv.length===1000?'Chart limited to 1,000 recent conversations.':'Counts are based on conversation creation time.'}</p></div>${readinessCard(ready)}</div><div class="grid cols4 mobile-metrics">${metric('Human replies',a.human_replies)}${metric('Resolved',a.resolved_conversations)}${metric('First response',a.avg_first_response_minutes==null?'—':a.avg_first_response_minutes+' min','Average in period')}${metric('Pending drafts',a.pending_ai_drafts)}</div></div>`;}
async function channels(){const tables=['widget_configs','email_accounts','whatsapp_accounts','telegram_accounts','x_accounts'];const r=await Promise.allSettled(tables.map(t=>rows(t,{select:t==='widget_configs'?'id,display_name,enabled,allowed_origins,public_key,brand_id':'id,status',limit:'50'})));state.widgets=r[0].status==='fulfilled'?r[0].value:[];const labels=['Website Chat','Email','WhatsApp','Telegram','X / Twitter'];return `<div class="stack"><div class="card"><h3>Connected channels</h3><p class="small muted">One inbox. Each channel keeps its own identity and policy.</p></div><div class="grid cols3">${r.map((result,i)=>{const ok=result.status==='fulfilled';const accounts=ok?result.value:[];const active=accounts.filter(a=>i===0?a.enabled:a.status==='connected').length;return `<div class="card stack"><div><h3>${labels[i]}</h3><p class="tiny muted">${ok?accounts.length+' configured account'+(accounts.length===1?'':'s'):'Connection state unavailable'}</p></div><div>${badge(ok?(active?'Connected':'Not connected'):'Could not load',active?'good':ok?'':'warning')}</div><p class="small">${i===0?'Human replies and approved automatic answers.':'Provider setup and delivery verification required.'}</p>${button(i===0?'Installation & widgets':'Connection guide','channel-guide',`data-channel="${i}"`,i===0?'':'primary')}</div>`;}).join('')}<div class="card stack"><div><h3>Voice</h3><p class="tiny muted">Optional module</p></div><div>${badge('Not part of this release')}</div><p class="small">The core release focuses on your support inbox and website chat.</p><a href="./site/docs/#channels" class="button">View channel support</a></div></div></div>`;}
function channelGuide(index){if(index!==0){modal('Channel connection guide',`<p>Provider connections need an authorised account, valid credentials and a verified delivery path. This release does not claim a channel is ready from a saved account record alone.</p><p>Use the existing provider admin connection flow, then test an inbound message and a reply before using it with customers.</p><a href="./site/docs/#channels" class="button primary">Read channel documentation</a>`);return;}modal('Website installation',state.widgets.map(w=>{const snippet=`<script src="https://deskroute-widget-v6-0-1.onrender.com/deskroute-widget.js" data-deskroute-key="${w.public_key}" defer></script>`;return `<div class="fact-item"><h3>${esc(w.display_name)}</h3>${badge(w.enabled?'Enabled':'Off',w.enabled?'good':'')}<p class="small">Allowed origins: ${esc((w.allowed_origins||[]).join(', ')||'No origins configured')}</p><pre>${esc(snippet)}</pre>${button('Copy snippet','copy-snippet',`data-key="${esc(w.public_key)}"`)}</div>`;}).join('')||empty('No widget configured','Create a widget through your workspace onboarding before installing it.'));}
async function help(){const centers=await rows('help_centers',{select:'id,public_key,title,subtitle,enabled,brand_id',limit:'50'},true);state.centers=centers;const articles=await rows('help_articles',{select:'id,title,slug,body,category,published,help_center_id',order:'sort_order.asc,created_at.desc',limit:'200'});state.articles=articles.filter(a=>centers.some(c=>c.id===a.help_center_id));return `<div class="stack"><div class="card row between wrap"><div><h3>Help Centre</h3><p class="small muted">Publish reviewed answers customers can browse and search.</p></div><div class="row">${brandSelect()}${['owner','admin'].includes(state.workspace.role)?button(centers.length?'New article':'Create help centre',centers.length?'new-article':'new-center','','primary'):''}</div></div>${centers.map(c=>`<div class="card row between wrap"><div><h3>${esc(c.title)}</h3><p class="small muted">${esc(c.subtitle||'Customer self-service')}</p>${badge(c.enabled?'Public centre enabled':'Centre is private',c.enabled?'good':'warning')}</div><div class="row">${c.enabled?`<a class="button" href="./help/?key=${encodeURIComponent(c.public_key)}" target="_blank" rel="noopener">Open public centre ↗</a>`:''}${['owner','admin'].includes(state.workspace.role)?button(c.enabled?'Make private':'Enable public centre','toggle-center',`data-id="${c.id}"`):''}</div></div>`).join('')}<div class="grid cols2">${state.articles.map(a=>`<div class="card"><div class="row between"><h3>${esc(a.title)}</h3>${badge(a.published?'Published':'Draft',a.published?'good':'warning')}</div><p class="small muted">${esc(a.category||'General')}</p><p class="fact-value small">${esc(a.body.slice(0,180))}${a.body.length>180?'…':''}</p><div class="row">${button('Read','read-article',`data-id="${a.id}"`)}${['owner','admin'].includes(state.workspace.role)?button('Edit','edit-article',`data-id="${a.id}"`)+button(a.published?'Unpublish':'Publish','toggle-article',`data-id="${a.id}"`):''}</div></div>`).join('')}</div>${!state.articles.length?`<div class="card">${empty('No articles yet','Create a draft and review it before publishing.')}</div>`:''}</div>`;}
function articleEditor(article={}){modal(article.id?'Edit article':'New help article',`<form id="articleForm" class="form"><div class="field"><label for="articleCenter">Help centre</label><select id="articleCenter">${options(state.centers.map(c=>[c.id,c.title]),article.help_center_id||state.centers[0]?.id)}</select></div>${field('articleTitle','Title',article.title||'','text','required maxlength="200"')}${field('articleSlug','URL slug',article.slug||'','text','required pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="how-to-book"')}${field('articleCategory','Category',article.category||'General')}<div class="field"><label for="articleBody">Article</label><textarea id="articleBody" required maxlength="20000" rows="10">${esc(article.body||'')}</textarea></div><p class="small muted">Articles are plain text. Saving an edit returns the article to draft for review.</p><div id="formError" class="notice danger hidden" role="alert"></div><div class="dialog-actions">${button('Cancel','close-modal')}<button class="button primary">Save draft</button></div></form>`);$('#articleForm').onsubmit=e=>submitForm(e,async()=>{const body={title:$('#articleTitle').value.trim(),slug:$('#articleSlug').value.trim(),body:$('#articleBody').value.trim(),category:$('#articleCategory').value.trim(),help_center_id:$('#articleCenter').value,published:false,updated_at:new Date().toISOString()};if(article.id)await api.patch('cxroute_help_articles',org(),article.id,body);else await api.table('cxroute_help_articles',{}, {method:'POST',body:{...body,organisation_id:org(),created_by:user()}});$('#modal').close();route('help');toast('Article saved as a draft.');});}
async function team(){const result=await api.rpc('cxroute_team_directory',{p_organisation_id:org()});state.members=result.members||[];return `<div class="stack"><div class="card"><h3>Team & roles</h3><p class="small muted">See who can help, what they can access and their current workload.</p></div><div class="grid wide-narrow"><div class="card"><h3>Members</h3><p class="small muted">Live workload. Device activity is not a guarantee of availability.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Role</th><th>Activity</th><th>Workload</th></tr></thead><tbody>${state.members.map(m=>`<tr><td><strong>${esc(m.display_name||m.member_email||'Team member')}</strong></td><td>${esc(pretty(m.role))}</td><td>${badge(m.last_seen_at?'Seen '+relative(m.last_seen_at):'Not registered',m.last_seen_at&&Date.now()-new Date(m.last_seen_at)<300000?'good':'')}</td><td>${Number(m.assigned_count||0)} assigned</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h3>Role permissions</h3><div class="stack" style="margin-top:22px">${['Owner — workspace ownership','Admin — manage workspace','Agent — reply and add notes','Viewer — read only','Custom — selected permissions'].map(r=>badge(r)).join('')}</div><p class="small muted" style="margin-top:24px">Member invitations and role changes require the administrator’s verified provisioning flow. No invitation is sent from this screen.</p></div></div></div>`;}
async function settings(){const [prefs,devices]=await Promise.all([rows('notification_preferences',{user_id:`eq.${user()}`,select:'new_message,assignment,sla_breach,urgent_only'}),rows('staff_devices',{user_id:`eq.${user()}`,select:'id,device_name,platform,last_seen_at,enabled,notification_mode',order:'last_seen_at.desc',limit:'30'})]);state.devices=devices;const p=prefs[0]||{new_message:false,assignment:true,sla_breach:true,urgent_only:false};const s=state.workspace.settings||{};return `<div class="stack"><div class="grid cols2"><div class="card"><h3>AI & human control</h3><p class="small muted">Choose how much DeskRoute can do automatically.</p><form id="aiForm" class="form"><div class="field"><label for="aiPolicy">AI mode</label><select id="aiPolicy" ${['owner','admin'].includes(state.workspace.role)?'':'disabled'}>${options([['suggest','Suggest only'],['approve','Review before sending'],['automatic','Automatic approved answers']],s.ai_mode||'approve')}</select></div>${field('aiConfidence','Minimum confidence (%)',Math.round((s.auto_answer_min_confidence??.9)*100),'number','min="90" max="100" required '+(['owner','admin'].includes(state.workspace.role)?'':'disabled'))}<p class="small muted">Unknown questions stay in the Human Queue. Automatic mode requires approved facts and at least 90% confidence.</p>${['owner','admin'].includes(state.workspace.role)?'<button class="button primary">Save AI policy</button>':''}</form></div><div class="card"><h3>Notifications</h3><p class="small muted">Only interrupt people when DeskRoute needs them.</p><form id="notificationForm">${[['new_message','New message alerts'],['assignment','Assignment alerts'],['sla_breach','SLA alerts'],['urgent_only','Urgent messages only']].map(([k,v])=>`<div class="toggle-row"><label for="pref-${k}">${v}</label><input id="pref-${k}" type="checkbox" ${p[k]?'checked':''}></div>`).join('')}<button class="button primary">Save preferences</button></form></div><div class="card"><h3>Workspace</h3>${kv({Business:state.workspace.profile?.display_name||state.workspace.name,Timezone:state.workspace.profile?.timezone||'Not set','Your role':pretty(state.workspace.role),'Default brand':state.brands.find(b=>b.is_default)?.name||'Not set'})}<label for="mobileWorkspace">Switch workspace</label><select id="mobileWorkspace">${options(state.workspaces.map(w=>[w.id,w.profile?.display_name||w.name]),org())}</select><div class="row wrap" style="margin-top:20px">${button('Brands','go-brands')}${button('Billing','go-billing')}${button('Audit log','go-audit')}${button('Sign out','signout')}</div></div><div class="card"><h3>Mobile & desktop</h3><p class="small muted">Install DeskRoute for a focused workspace on your phone or computer. In-app alerts refresh while the app is open.</p>${button('Install DeskRoute','install','','primary')}<p class="notice warning" style="margin-top:16px">Closed-app background push is not enabled in this release. Keep DeskRoute open to receive in-app updates.</p><p class="tiny muted">Version ${VERSION}</p></div></div><div class="card"><h3>Your registered devices</h3><div class="stack">${devices.map(d=>`<div class="row between wrap"><div><strong>${esc(d.device_name||pretty(d.platform))}</strong><p class="tiny muted">Last seen ${date(d.last_seen_at)} · ${esc(d.notification_mode)}</p></div>${badge(d.enabled?'Active':'Disabled',d.enabled?'good':'')}</div>`).join('')||'<p class="muted">No registered devices.</p>'}</div></div></div>`;}
async function notifications(){const r=await api.onboard('notifications',org());state.notifications=r.notifications||[];setNotificationCount(r.unread);return `<div class="stack"><div class="section-head"><h2>When your team needs you</h2><p>Assignment, mention and SLA notifications · updates while DeskRoute is open</p></div>${state.notifications.map(n=>`<div class="card notification ${n.read_at?'':'unread'}"><div class="row between wrap"><h3>${esc(n.title)}</h3>${badge(n.read_at?'Read':'Unread',n.read_at?'':'good')}</div><p>${esc(n.body_preview||'Open the conversation for details.')}</p><p class="tiny muted">${date(n.created_at)}</p><div class="row">${n.conversation_id?button('Open conversation','open-notification',`data-id="${n.id}"`,'primary'):''}${!n.read_at?button('Mark read','read-notification',`data-id="${n.id}"`):''}</div></div>`).join('')||`<div class="card">${empty('No notifications','New assignments and mentions will appear here.')}</div>`}</div>`;}
function setNotificationCount(count){$('#alertCount').textContent=count>99?'99+':count;$('#alertCount').classList.toggle('hidden',!count);$('#alertsButton').setAttribute('aria-label',`Notifications${count?', '+count+' unread':''}`);}
async function refreshNotifications(){if(!state.workspace||document.hidden||!navigator.onLine)return;const workspace=org();try{const result=await api.onboard('notifications',workspace);if(workspace!==org())return;state.notifications=result.notifications||[];setNotificationCount(result.unread);if(state.device)await api.onboard('device_heartbeat',workspace,{deviceId:state.device});}catch{/* Do not replace the current editor when a background refresh fails. */}}
async function registerDevice(){const workspace=org();let installationId=localStorage.getItem('dr-device');if(!installationId){installationId=crypto.randomUUID();localStorage.setItem('dr-device',installationId);}const agent=navigator.userAgent;const platform=/Android/i.test(agent)?'android':/iPhone|iPad/i.test(agent)?'ios':/Windows/i.test(agent)?'windows':/Mac/i.test(agent)?'macos':'web';try{const r=await api.onboard('register_device',workspace,{installationId,deviceName:pretty(platform)+' browser',platform,appVersion:VERSION,notificationMode:'poll'});if(workspace===org())state.device=r.device?.id;}catch{toast('In-app alerts are available, but this device could not be registered.',true);}clearInterval(state.timer);state.timer=setInterval(refreshNotifications,30000);await refreshNotifications();}
async function review(){const ds=await rows('ai_drafts',{status:'eq.pending',select:'id,conversation_id,proposed_reply,confidence,created_at',order:'created_at.asc',limit:'100'});state.aiDrafts=ds;return `<div class="stack"><div class="notice"><strong>Review before sending</strong><p>Check the answer against your business policy. Opening a draft takes you to its conversation, where you can edit and send it.</p></div><div class="grid cols2">${ds.map(d=>`<div class="card"><div class="row between">${badge('Needs review','warning')}<span class="tiny muted">${Math.round(d.confidence*100)}% confidence</span></div><p class="fact-value" style="margin-top:16px">${esc(d.proposed_reply)}</p>${button('Review in conversation','use-draft',`data-id="${d.id}"`,'primary')}<p class="tiny muted" style="margin-top:16px">${date(d.created_at)}</p></div>`).join('')}</div>${!ds.length?empty('No drafts waiting','Your review queue is clear.'):''}</div>`;}
async function autosetup(){const scans=await rows('autosetup_runs',{select:'id,website_url,scan_status,facts_proposed,detected_platform,last_error,created_at',order:'created_at.desc',limit:'20'},true);return `<div class="stack"><div class="grid cols2"><div class="card"><h3>Learn from your website</h3><p class="small muted">Scan a website you are authorised to manage. Proposed facts stay pending until you approve them.</p><form id="scanForm" class="form"><div class="field"><label for="scanBrand">Brand</label><select id="scanBrand" required>${options(state.brands.map(b=>[b.id,b.name]),state.brand)}</select></div>${field('scanUrl','Website URL',state.brands.find(b=>b.id===state.brand)?.website_url||'','url','required placeholder="https://example.com"')}<label class="row"><input type="checkbox" required> I’m authorised to scan this business website.</label><button class="button primary" ${allowed('knowledge.manage')?'':'disabled'}>Scan website</button><p id="scanStatus" class="small muted" role="status"></p></form></div><div class="card"><h3>What happens next?</h3><ol class="check-list"><li>DeskRoute reads the accessible website pages.</li><li>Facts and FAQs are proposed for review.</li><li>You check prices, policies, hours and contact details.</li><li>Approved facts become available to your AI.</li></ol><p class="small muted">A scan does not install the widget or approve the facts automatically.</p></div></div><div class="card"><h3>Recent scans</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Website</th><th>Platform</th><th>Facts</th><th>Status</th></tr></thead><tbody>${scans.map(s=>`<tr><td>${esc(s.website_url)}</td><td>${esc(s.detected_platform||'—')}</td><td>${Number(s.facts_proposed||0)}</td><td>${badge(pretty(s.scan_status),['complete','completed'].includes(s.scan_status)?'good':'warning')}<p class="tiny muted">${esc(s.last_error||'')}</p></td></tr>`).join('')}</tbody></table></div></div></div>`;}
async function brands(){return `<div class="grid cols2">${state.brands.map(b=>`<div class="card"><h3>${esc(b.name)}</h3>${badge(b.is_default?'Default brand':'Enabled','good')}${kv({Website:b.website_url,'Support email':b.support_email})}</div>`).join('')}</div>`;}
async function billing(){const [subscriptions,plans]=await Promise.all([rows('subscriptions',{select:'plan_code,status',limit:'1'}),api.table('cxroute_plans',{select:'code,name,seat_limit,brand_limit,monthly_conversation_limit,monthly_ai_draft_limit',order:'code.asc'})]);return `<div class="stack"><div class="card"><h3>Current plan</h3>${kv({Plan:subscriptions[0]?.plan_code||'No subscription',Status:subscriptions[0]?.status||'Not configured'})}<p class="small muted">Billing checkout and paid entitlements must be verified before accepting paid subscriptions. Contact your onboarding lead for commercial terms.</p></div><div class="grid cols3">${plans.map(p=>`<div class="card"><h3>${esc(p.name)}</h3>${kv({Seats:p.seat_limit??'Custom',Brands:p.brand_limit??'Custom',Conversations:p.monthly_conversation_limit??'Custom','AI drafts':p.monthly_ai_draft_limit??'Custom'})}</div>`).join('')}</div></div>`;}
async function audit(){const logs=await rows('audit_log',{select:'id,actor_type,action,entity_type,created_at,safe_metadata',order:'created_at.desc',limit:'100'});return `<div class="card"><h3>Recent audit events</h3><p class="small muted">Latest 100 events in this workspace</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity</th></tr></thead><tbody>${logs.map(a=>`<tr><td>${date(a.created_at)}</td><td>${esc(a.actor_type)}</td><td>${esc(pretty(a.action))}</td><td>${esc(a.entity_type)}</td></tr>`).join('')}</tbody></table></div></div>`;}
const renderers={inbox,human,brain,automations,analytics,channels,help,team,settings,alerts:notifications,review,autosetup,brands,billing,audit};
function bindPage(){
 if($('#inboxSearch'))$('#inboxSearch').oninput=e=>{state.search=e.target.value;$('#globalSearch').value=state.search;$('#ticketRows').innerHTML=ticketRows();};
 if($('#brandSelect'))$('#brandSelect').onchange=e=>{state.brand=e.target.value;renderRoute();};
 if($('#mobileWorkspace'))$('#mobileWorkspace').onchange=e=>switchWorkspace(e.target.value);
 if($('#aiForm'))$('#aiForm').onsubmit=e=>submitForm(e,async()=>{const ai_mode=$('#aiPolicy').value,confidence=Number($('#aiConfidence').value)/100;if(confidence<.9||confidence>1)throw new Error('Choose a confidence threshold from 90 to 100%.');await api.patch('cxroute_settings',org(),null,{ai_mode,auto_answer_min_confidence:confidence,updated_at:new Date().toISOString()});state.workspace.settings={...state.workspace.settings,ai_mode,auto_answer_min_confidence:confidence};renderNav();toast('AI policy saved.');});
 if($('#notificationForm'))$('#notificationForm').onsubmit=e=>submitForm(e,async()=>{const body={organisation_id:org(),user_id:user(),updated_at:new Date().toISOString()};for(const k of ['new_message','assignment','sla_breach','urgent_only'])body[k]=$('#pref-'+k).checked;await api.table('cxroute_notification_preferences',{on_conflict:'organisation_id,user_id'},{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body});toast('Notification preferences saved.');});
 if($('#scanForm'))$('#scanForm').onsubmit=e=>submitForm(e,async()=>{const websiteUrl=$('#scanUrl').value.trim(),brandId=$('#scanBrand').value;const parsed=new URL(websiteUrl);if(!['http:','https:'].includes(parsed.protocol))throw new Error('Enter a full http or https website URL.');$('#scanStatus').textContent='Scanning website pages. This may take a minute…';const r=await api.edge('cxroute-website-scan',{organisationId:org(),brandId,websiteUrl});toast(`Scan completed: ${Number(r.factsProposed||0)} facts proposed for review.`);state.brand=brandId;route('brain');});
}
async function switchWorkspace(id){api.changeContext();state.routeId++;state.threadId++;clearInterval(state.timer);$('#modal').close();state.workspace=state.workspaces.find(w=>w.id===id);$('#workspace').value=id;try{await loadWorkspaceData();await renderRoute();registerDevice();}catch(e){toast(e.message,true);}}
async function action(name,el){
 if(name==='close-modal')return $('#modal').close();
 if(name==='open-menu')return menu(true);
 if(name==='retry')return renderRoute();
 if(name.startsWith('go-'))return route(name.slice(3));
 if(name==='back-inbox')return route('inbox');
 if(name==='ticket-status')return ticketUpdate({status:el.dataset.status});
 if(name==='add-fact')return factEditor();
 if(name==='edit-fact')return factEditor(state.facts.find(f=>f.id===el.dataset.id));
 if(name==='teach-gap')return factEditor({},el.dataset.question);
 if(name==='approve-fact'||name==='reject-fact'){const status=name==='approve-fact'?'approved':'rejected';await api.patch('cxroute_knowledge_facts',org(),el.dataset.id,{review_status:status,approved_by:status==='approved'?user():null,approved_at:status==='approved'?new Date().toISOString():null,updated_at:new Date().toISOString()},{review_status:'eq.pending'});toast('Fact '+status+'.');return renderRoute();}
 if(name==='approve-learning'){await api.rpc('cxroute_approve_learning_suggestion',{p_suggestion_id:el.dataset.id});toast('Answer approved.');return renderRoute();}
 if(name==='new-rule')return ruleEditor();
 if(name==='edit-rule')return ruleEditor(state.rules.find(r=>r.id===el.dataset.id));
 if(name==='toggle-rule'){const r=state.rules.find(r=>r.id===el.dataset.id);await api.patch('cxroute_routing_rules',org(),r.id,{enabled:!r.enabled,updated_at:new Date().toISOString()});toast(r.enabled?'Rule switched off.':'Rule switched on.');return renderRoute();}
 if(name==='channel-guide')return channelGuide(Number(el.dataset.channel));
 if(name==='copy-snippet'){await navigator.clipboard.writeText(`<script src="https://deskroute-widget-v6-0-1.onrender.com/deskroute-widget.js" data-deskroute-key="${el.dataset.key}" defer></script>`);return toast('Installation snippet copied.');}
 if(name==='new-article')return articleEditor();
 if(name==='edit-article')return articleEditor(state.articles.find(a=>a.id===el.dataset.id));
 if(name==='read-article'){const a=state.articles.find(a=>a.id===el.dataset.id);return modal(a.title,`<p class="fact-value">${esc(a.body)}</p>`);}
 if(name==='toggle-article'){const a=state.articles.find(a=>a.id===el.dataset.id);await api.patch('cxroute_help_articles',org(),a.id,{published:!a.published,updated_at:new Date().toISOString()});toast(a.published?'Article unpublished.':'Article published. It is public only when its help centre is enabled.');return renderRoute();}
 if(name==='toggle-center'){const c=state.centers.find(c=>c.id===el.dataset.id);await api.patch('cxroute_help_centers',org(),c.id,{enabled:!c.enabled,updated_at:new Date().toISOString()});return renderRoute();}
 if(name==='new-center'){modal('Create help centre',`<form id="centerForm" class="form">${field('centerTitle','Help centre title',state.workspace.profile?.display_name+' Help','text','required maxlength="160"')}<p class="small muted">The new centre starts private. Add and review articles before enabling public access.</p><div id="formError" class="notice danger hidden"></div><button class="button primary">Create private centre</button></form>`);$('#centerForm').onsubmit=e=>submitForm(e,async()=>{await api.table('cxroute_help_centers',{}, {method:'POST',body:{organisation_id:org(),brand_id:state.brand,title:$('#centerTitle').value.trim(),enabled:false,allow_contact_form:false,public_key:'help_'+crypto.randomUUID().replaceAll('-','')}});$('#modal').close();renderRoute();});return;}
 if(name==='read-notification'||name==='open-notification'){const n=state.notifications.find(n=>n.id===el.dataset.id);await api.onboard('mark_notification_read',org(),{notificationId:n.id,deviceId:state.device});if(name==='open-notification'&&n.conversation_id)route('inbox',n.conversation_id);else await renderRoute();return refreshNotifications();}
 if(name==='use-draft'){const d=state.aiDrafts.find(d=>d.id===el.dataset.id);state.drafts.set(d.conversation_id,{reply:d.proposed_reply,note:'',aiDraftId:d.id});state.mode='reply';return route('inbox',d.conversation_id);}
 if(name==='install'){if(state.installPrompt){await state.installPrompt.prompt();const result=await state.installPrompt.userChoice;if(result.outcome==='accepted')state.installPrompt=null;}else modal('Install DeskRoute',`<p>On iPhone or iPad, open DeskRoute in Safari, choose <strong>Share → Add to Home Screen</strong>.</p><p>On Android, choose <strong>Install app</strong> or <strong>Add to Home screen</strong> in your browser menu. On a desktop, look for the install icon in the address bar.</p><p class="notice">In-app alerts work while DeskRoute is open. Background push is not enabled.</p>`);return;}
 if(name==='signout'){try{await api.logout();}catch{toast('Signed out on this device. Server session revocation could not be confirmed.',true);}finally{showLogin();location.hash='';}return;}
}
document.addEventListener('click',async event=>{const page=event.target.closest('[data-page]'),cv=event.target.closest('[data-conversation]'),filter=event.target.closest('[data-filter]'),compose=event.target.closest('[data-compose]'),control=event.target.closest('[data-action]');
 if(page){route(page.dataset.page);return;}if(cv){route('inbox',cv.dataset.conversation);return;}if(filter){state.filter=filter.dataset.filter;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b===filter));$('#ticketRows').innerHTML=ticketRows();return;}
 if(compose){state.mode=compose.dataset.compose;try{await openThread(state.selected);}catch(e){toast(e.message,true);}return;}
 if(control&&!control.disabled){const disabled=control.disabled;control.disabled=true;try{await action(control.dataset.action,control);}catch(error){toast(error.message,true);}finally{if(control.isConnected)control.disabled=disabled;}}
});
$('#menuButton').onclick=()=>menu(true);$('#closeMenu').onclick=()=>{menu(false);$('#menuButton').focus();};$('#menuShade').onclick=()=>menu(false);$('#alertsButton').onclick=()=>route('alerts');
$('#workspace').onchange=e=>switchWorkspace(e.target.value);
$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){state.search=e.target.value;route('inbox');}});
$('#loginForm').onsubmit=async event=>{event.preventDefault();const submit=$('button',event.currentTarget);submit.disabled=true;$('#loginError').classList.add('hidden');try{await api.login($('#email').value.trim(),$('#password').value);$('#password').value='';await start();}catch(error){$('#loginError').textContent=error.message;$('#loginError').classList.remove('hidden');}finally{submit.disabled=false;}};
window.addEventListener('hashchange',renderRoute);
window.addEventListener('keydown',e=>{if(e.key==='Escape')menu(false);});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e;});
window.addEventListener('online',()=>{$('#offlineBanner').classList.add('hidden');refreshNotifications();});window.addEventListener('offline',()=>$('#offlineBanner').classList.remove('hidden'));
window.addEventListener('storage',event=>{if(event.key==='drs'&&!event.newValue){api.clear();showLogin('Signed out in another tab.');}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshNotifications();});
async function start(){await loadWorkspace();$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');await renderRoute();registerDevice();}
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(!navigator.onLine)$('#offlineBanner').classList.remove('hidden');
if(api.session)start().catch(error=>showLogin(error.message));
